"use strict";(globalThis.webpackChunkmy_website||=[]).push([[68206],{58686(e){e.exports=JSON.parse('{"slug":"controlled-stake","title":"Controlled Stake","short":"The total ada associated with a stake pool, combining operator pledge and all delegations.","category":"consensus","aliases":["Pool Stake"],"mentalModel":null,"related":["live-stake","stake-pool","pledge","pool-saturation"],"sources":[],"link":null,"level":"intermediate","body":"The total ada associated with a stake pool: the operator\'s own pledge plus every delegator\'s ada. Controlled stake is what the protocol uses to weight a pool\'s chance of producing blocks in a given epoch, proportional to the pool\'s share of total controlled stake across the network.\\n\\nA pool\'s controlled stake is compared against the saturation threshold (set by the `k` parameter) to decide whether additional delegation will keep earning full rewards."}')}}]);